<?php
require_once __DIR__.'/bot-service.php';
require_once __DIR__.'/bot-employee.php';
function opsOwnerPlan($pdo,$uid,$prompt,$cfg){$prompt=opsText($prompt,8000);if(!$prompt)throw new RuntimeException('Опишите задачу');$catalog=opsCatalog($pdo,$uid);$items=array_map(fn($i)=>['id'=>(int)$i['id'],'name'=>$i['item_name'],'price'=>$i['item_price'],'availability'=>$i['details']['availability']??'unknown'],array_slice($catalog,0,200));$newOrders=opsOne($pdo,"SELECT COUNT(*) AS n FROM ops_orders WHERE user_id=? AND status='new'",[$uid]);$r=opsAI($cfg,'Ты помощник владельца. Сначала проанализируй запрос и данные, затем предложи до8 проверяемых действий. Ничего ещё не выполнено. JSON {"summary":"ответ или уточнение","actions":[{"type":"catalog_update","item_id":1,"price":1200,"availability":"available|out_of_stock|preorder|unknown"},{"type":"task","name":"задача","text":"детали"}]}. В catalog_update включай только явно запрошенные поля. Если неясно какая позиция или цена, уточни и не меняй её. Не создавай произвольные SQL/команды, сообщения, платежи или заказы. Для аналитических вопросов actions может быть пустым.', ['request'=>$prompt,'catalog'=>$items,'new_orders'=>(int)$newOrders['n'],'open_tickets'=>array_map(fn($r)=>['name'=>$r['data']['name'],'status'=>$r['data']['status']],array_filter(opsRecords($pdo,$uid,'ops_ticket'),fn($r)=>$r['data']['status']!=='resolved'))]);$actions=[];$seenItems=[];foreach(array_slice($r['actions']??[],0,8) as $a){if(($a['type']??'')==='catalog_update'){$item=opsItem($pdo,$uid,(int)($a['item_id']??0));$itemKey=(int)$item['id'];if(isset($seenItems[$itemKey]))continue;$seenItems[$itemKey]=true;$before=opsItemSnapshot($item);$after=$before;if(isset($a['price']))$after['item_price']=round(opsNumber($a['price'],0.01),2);if(isset($a['availability'])){if(!in_array($a['availability'],['available','out_of_stock','preorder','unknown']))throw new RuntimeException('ИИ предложил неизвестный статус');$after['details']['availability']=$a['availability'];}if(!opsSame($before,$after))$actions[]=['kind'=>'catalog','action'=>'update','id'=>(int)$item['id'],'before'=>$before,'after'=>$after];}elseif(($a['type']??'')==='task'&&!empty($a['name']))$actions[]=['kind'=>'tasks','action'=>'add','after'=>['name'=>opsText($a['name']),'text'=>opsText($a['text']??'',4000),'status'=>'Новая']];}
    $plan=['name'=>mb_substr($prompt,0,100),'prompt'=>$prompt,'summary'=>opsText($r['summary']??'',10000),'state'=>'proposed','steps'=>[['name'=>'Данные проверены','status'=>'done'],['name'=>'Изменения подготовлены','status'=>'done'],['name'=>'Подтверждение владельца','status'=>'waiting'],['name'=>'Выполнение и проверка','status'=>'waiting']],'actions'=>$actions,'created_at'=>opsNow()];$id=opsRecord($pdo,$uid,'ops_plan',$plan);return ['id'=>$id]+$plan;
}
function opsOwnerApply($pdo,$uid,$id,$selected,$actor=null){try{return opsTx($pdo,$uid,function()use($pdo,$uid,$id,$selected,$actor){$r=opsGetRecord($pdo,$uid,$id,'ops_plan',true);$p=$r['data'];if($p['state']!=='proposed')throw new RuntimeException('План уже обработан. Подготовьте новый.');if(!is_array($selected)||!count($selected))throw new RuntimeException('Выберите действия');$selected=array_unique(array_map('intval',$selected));$changes=[];foreach($selected as $n){$a=$p['actions'][$n]??null;if(!$a)throw new RuntimeException('Неизвестное действие');if($a['kind']==='catalog'){if(!opsSame(opsItemSnapshot(opsItem($pdo,$uid,$a['id'])),$a['before']))throw new RuntimeException('Карточка изменилась после подготовки плана. Создайте новый план.');opsWriteItem($pdo,$uid,$a['id'],$a['after']);}else $a['id']=opsRecord($pdo,$uid,'tasks',$a['after']);$changes[]=$a;}$p['state']='executed';$p['steps'][2]['status']='done';$p['steps'][3]['status']='done';$p['result']='Выполнено действий: '.count($changes);$p['executed_at']=opsNow();$audit=opsAudit($pdo,$uid,'owner_plan',$id,['changes'=>$changes],$actor);$p['audit_id']=$audit;opsPutRecord($pdo,$uid,$id,$p);return ['ok'=>true,'count'=>count($changes),'audit_id'=>$audit];});}catch(Throwable $e){if(!$pdo->inTransaction()){try{$r=opsGetRecord($pdo,$uid,$id,'ops_plan');if($r['data']['state']==='proposed'){$r['data']['state']='failed';$r['data']['error']=$e instanceof PDOException?'Ошибка сохранения. Изменения не применены.':opsText($e->getMessage(),500);opsPutRecord($pdo,$uid,$id,$r['data']);}}catch(Throwable $ignored){}}throw $e;}}
function opsQuoteText($quote,$kk=false){$lines=[];if($quote['is_demo'])$lines[]=$kk?'Демонстрациялық тапсырыс — нақты сату емес.':'Демонстрационный заказ — это пример, не реальная продажа.';foreach($quote['items'] as $r)$lines[]=$r['name'].' × '.$r['quantity'].' — '.number_format($r['total'],2,',',' ').' ₸';$lines[]=($kk?'Барлығы: ':'Итого: ').number_format($quote['total'],2,',',' ').' ₸';return implode("\n",$lines);}
function opsBotHandleCore($pdo,$owner,$chat,$text,$cfg,$sourceId=0){
    $uid=(int)$owner['id'];$state=opsChat($pdo,$uid,$chat);$kk=(bool)preg_match('/[әғқңөұүһі]/iu',$text);$yes=(bool)preg_match('/^(?:да[,! ]*)?(?:подтверждаю|оформляйте|подтвердить заказ|подтвердить запись|применить изменения|да|иә|растаймын|растау)[.!\s]*$/iu',trim($text));$no=(bool)preg_match('/^(?:отмена|отменить|не надо|жоқ|бас тарту)[.!\s]*$/iu',trim($text));
    $ownerLogin=preg_match('/^(?:я владелец|вход владельца|мен иесімін)\s+(\d{8})[.!\s]*$/iu',trim($text),$m);
    if($sourceId&&($ownerLogin||($state['owner_until']??0)>time())){$incoming=opsGetRecord($pdo,$uid,$sourceId,'telegram');$incoming['data']['owner_private']=true;if($ownerLogin)$incoming['data']['text']='[Вход владельца]';opsPutRecord($pdo,$uid,$sourceId,$incoming['data']);}
    if($ownerLogin){
        opsRateLimit($pdo,'owner-code:'.$uid.':'.$chat,5,600);
        $ok=opsTx($pdo,$uid,function()use($pdo,$uid,$m){foreach(opsRecords($pdo,$uid,'ops_owner_code') as $r)if(($r['data']['expires']??0)>time()&&hash_equals($r['data']['hash'],hash('sha256',$m[1]))){opsExec($pdo,'UPDATE aulieata_records SET archived=1 WHERE id=? AND user_id=?',[$r['id'],$uid]);return true;}return false;});
        if(!$ok)return 'Код недействителен. Получите новый код в приложении → ИИ-агент.';
        $state=['owner_until'=>time()+3600];opsSaveChat($pdo,$uid,$chat,$state);return 'Режим владельца включён на 60 минут. Напишите или скажите задачу. Изменения выполняются после вашего подтверждения. Для выхода: «Режим клиента».';
    }
    if(preg_match('/^(режим клиента|выйти из режима владельца|клиент режимі)[.!\s]*$/iu',trim($text))){unset($state['owner_until'],$state['owner_plan']);opsSaveChat($pdo,$uid,$chat,$state);return $kk?'Клиент режимі қосылды.':'Включён режим клиента.';}
    if(($state['owner_until']??0)>time()){
        if($no){unset($state['owner_plan']);opsSaveChat($pdo,$uid,$chat,$state);return 'Изменения отменены.';}
        if($yes&&!empty($state['owner_plan'])){$p=opsGetRecord($pdo,$uid,$state['owner_plan'],'ops_plan')['data'];$r=opsOwnerApply($pdo,$uid,$state['owner_plan'],array_keys($p['actions']),'telegram_owner');unset($state['owner_plan']);opsSaveChat($pdo,$uid,$chat,$state);return 'Готово. Выполнено действий: '.$r['count'].'. История и отмена доступны в приложении.';}
        if((opsSettings($pdo,$uid)['bot_mode']??'ai')!=='ai')return 'Для ИИ-планов включите режим с ИИ в настройках бота. Бесплатный режим обслуживает клиентов по каталогу.';
        $p=opsOwnerPlan($pdo,$uid,$text,$cfg);$state['owner_plan']=$p['id'];opsSaveChat($pdo,$uid,$chat,$state);$lines=[$p['summary']];foreach($p['actions'] as $a)$lines[]=$a['kind']==='catalog'?$a['after']['item_name'].': '.$a['before']['item_price'].' → '.$a['after']['item_price'].' ₸; наличие: '.(['available'=>'доступно','out_of_stock'=>'закончилось','preorder'=>'под заказ','unknown'=>'уточнить'][$a['after']['details']['availability']]):'Задача: '.$a['after']['name'];if($p['actions'])$lines[]='Изменения ещё не сохранены. Напишите «Подтверждаю» или «Отмена».';return implode("\n",$lines);
    }
    if(!empty($state['ticket_id'])){$r=opsGetRecord($pdo,$uid,$state['ticket_id'],'ops_ticket');$d=$r['data'];if($d['status']!=='resolved'){$d['messages'][]=['role'=>'client','text'=>opsText($text,8000),'at'=>opsNow()];$d['messages']=array_slice($d['messages'],-100);opsPutRecord($pdo,$uid,$r['id'],$d);return $kk?'Хабарламаңыз қызметкердің кіріс жәшігіне қосылды.':'Сообщение добавлено в обращение сотруднику. Он увидит его в рабочем кабинете.';}unset($state['ticket_id']);}
    $employee=botEmployeeTurn($pdo,$uid,(string)$chat,$text,$state,publicCatalogData($pdo,$uid,$text));
    if(isset($employee['reply']))return $employee['reply'];
    if($no){unset($state['pending'],$state['budget_options'],$state['booking_flow'],$state['checkout_step']);opsSaveChat($pdo,$uid,$chat,$state);return $kk?'Ағымдағы жоба жойылды. Расталған тапсырысты жою үшін қызметкерге жазыңыз.':'Текущий черновик отменён. Для отмены уже созданного заказа напишите «Нужен сотрудник».';}
    if($yes&&!empty($state['pending'])){$pending=$state['pending'];if(($pending['expires']??0)<time()){unset($state['pending']);opsSaveChat($pdo,$uid,$chat,$state);return $kk?'Ұсыныстың уақыты өтті. Сұрауды қайталаңыз.':'Предложение устарело. Повторите запрос, чтобы проверить цену и наличие.';}$settings=opsSettings($pdo,$uid);if(empty($settings[$pending['kind']==='booking'?'bookings_enabled':'orders_enabled'])){unset($state['pending']);opsSaveChat($pdo,$uid,$chat,$state);return $kk?'Қабылдау уақытша өшірілген. Қызметкерге жүгініңіз.':'Приём временно выключен владельцем. Обратитесь к сотруднику.';}$r=$pending['kind']==='booking'?opsAppointmentSave($pdo,$uid,$pending['data'],'telegram',$chat):opsCreateOrder($pdo,$uid,$pending['data'],'telegram',$chat);unset($state['pending']);opsSaveChat($pdo,$uid,$chat,$state);return $pending['kind']==='booking'?($kk?'Жазылу өтінімі №':'Заявка на запись №').$r['id'].'. '.$r['starts_at'].' (UTC+5). '.($r['status']==='confirmed'?($kk?'Жазылу расталды.':'Запись подтверждена.'):($kk?'Қызметкердің растауын күтіңіз.':'Ожидайте подтверждения сотрудника.')):(!empty($r['is_demo'])?($kk?'Демонстрациялық ':'Демонстрационный '):'').($kk?'тапсырыс №':'заказ №').$r['id'].($kk?' сақталды. Қызметкер оны жұмыс кабинетінде көреді. Төлем жүргізілген жоқ.':' создан. Сотрудник увидит его в рабочем кабинете. Оплата не проводилась.');}
    $settings=opsSettings($pdo,$uid);$catalog=publicCatalogData($pdo,$uid,$text);$resources=opsAll($pdo,'SELECT id,name,payload FROM ops_resources WHERE user_id=? AND active=1',[$uid]);foreach($resources as &$resource){$resource['services']=json_decode($resource['payload'],true)['service_ids']??[];unset($resource['payload']);}
    $intent=$employee['intent']??botLocalIntent($catalog,$text);
    // Keep full conversation/booking parsing in AI mode; local parsing serves the free mode.
    if((empty($employee['intent'])||empty($intent['items']))&&($settings['bot_mode']??'ai')!=='free'&&in_array($intent['intent']??'', ['order','booking'],true))$intent=null;
    if($intent===null){$quick=botQuickAnswer($pdo,$uid,$text,$catalog);if($quick!==null)return $quick;if(($settings['bot_mode']??'ai')==='free')return botUnavailable($kk);}
    if($intent===null){
    $history=[];foreach(opsAll($pdo,"SELECT payload FROM aulieata_records WHERE user_id=? AND kind='telegram' AND archived=0 AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.chat_id')) AS BINARY)=CAST(? AS BINARY) ORDER BY id DESC LIMIT 8",[$uid,(string)$chat]) as $row){$h=json_decode($row['payload'],true);if(!empty($h['owner_private']))continue;$history[]=['client'=>opsText($h['text']??'',1200),'assistant'=>opsText($h['reply']??'',1200)];}
    if(($settings['bot_mode']??'ai')==='cloud'){try{$intent=botCloudIntent($pdo,$uid,$text,$state,$catalog,$resources,array_reverse($history),$cfg);}catch(RuntimeException $e){if($e instanceof PDOException)throw $e;return botUnavailable($kk);}}else{
    try{$intent=opsAI($cfg,'Определи намерение клиента бизнеса. Ты не владелец и не можешь менять цены/настройки. JSON {"intent":"question|order|booking|budget|handoff","items":[{"item_id":1,"quantity":2}],"client":"имя если известно","phone":"если дан","pickup_at":"пожелание по получению","resource_id":null,"starts_at":"YYYY-MM-DD HH:MM:SS или пусто","reminder_optin":false,"budget":null,"people":1,"campaign_code":"если явно указан","clarification":"вопрос при нехватке данных","demand":{"reason":"missing_item|price|no_slot|none","topic":"что искали"}}. Справочные вопросы о наличии/цене — question, не order. Для заказа/записи нужны явное желание оформить и точные доступные item_id. Никогда не придумывай позицию/цену/время/номер. Для booking нужен ресурс и точное время; если ресурс один подходящий, можешь выбрать его. reminder_optin true только при явном согласии на напоминание. Относительные даты считай от given_now в UTC+5. Для budget используй общий бюджет. demand отмечай только при явном запросе отсутствующего товара, отказе из-за цены или нехватке времени. Простое спрашивание цены не является отказом. clarification и ответы на языке клиента.', ['history'=>array_reverse($history),'message'=>$text,'given_now'=>opsNow(),'catalog'=>$catalog,'resources'=>$resources,'pending'=>$state['pending']['data']??null,'budget_options'=>$state['budget_options']??[]]);}catch(RuntimeException $e){if($e instanceof PDOException)throw $e;return botUnavailable($kk);}
    }
    }
    $demand=$intent['demand']??[];if($sourceId&&in_array($demand['reason']??'', ['missing_item','price','no_slot']))opsExec($pdo,'INSERT IGNORE INTO ops_demands(user_id,source_id,chat_id,reason,topic,excerpt,created_at) VALUES(?,?,?,?,?,?,?)',[$uid,$sourceId,$chat,$demand['reason'],opsText($demand['topic']??'Запрос'),opsText($text,1500),opsNow()]);
    if(($intent['intent']??'question')==='handoff'){$history=opsAll($pdo,"SELECT payload FROM aulieata_records WHERE user_id=? AND kind='telegram' AND archived=0 ORDER BY id DESC LIMIT 100",[$uid]);$context=[];foreach($history as $h){$v=json_decode($h['payload'],true);if(empty($v['owner_private'])&&(string)($v['chat_id']??'')===(string)$chat)$context[]=opsText($v['text']??'',700).' → '.opsText($v['reply']??'',700);if(count($context)>=5)break;}$id=opsTicket($pdo,$uid,['name'=>'Telegram · помощь сотрудника','channel'=>'telegram','chat_id'=>$chat,'text'=>$text,'summary'=>implode("\n",array_reverse($context))]);$state['ticket_id']=$id;unset($state['pending']);opsSaveChat($pdo,$uid,$chat,$state);return $kk?'Қызметкерге өтінім ашылды. Соңғы әңгіме оған жұмыс кабинетінде көрінеді.':'Создал обращение сотруднику. Последние сообщения доступны ему в рабочем кабинете; он сможет ответить здесь.';}
    if(($intent['intent']??'')==='budget'){$options=opsBudget($pdo,$uid,['budget'=>$intent['budget']??0,'people'=>$intent['people']??1,'preferences'=>$text],$cfg);$state['budget_options']=$options;opsSaveChat($pdo,$uid,$chat,$state);$lines=[];foreach($options as $i=>$o)$lines[]=($i+1).'. '.$o['name']."\n".opsQuoteText($o['quote'],$kk);$lines[]=$kk?'Қай нұсқаны таңдайсыз?':'Какой вариант выбираете?';return implode("\n\n",$lines);}
    if(($intent['intent']??'')==='order'){
        if(!$settings['orders_enabled'])return $kk?'Тапсырыс қабылдауды иесі әлі қоспаған. Қызметкерге жүгініңіз.':'Приём заказов через бота ещё не включён владельцем. Можно уточнить ассортимент или попросить сотрудника.';if(empty($intent['items']))return opsText($intent['clarification']??($kk?'Не тапсырыс бергіңіз келеді?':'Что и в каком количестве хотите заказать?'),1000);$quote=opsQuote($pdo,$uid,$intent['items'],$intent['campaign_code']??'');$data=['items'=>$intent['items'],'quote_hash'=>$quote['hash'],'request_key'=>'tg-'.bin2hex(random_bytes(16)),'client'=>($intent['client']??'')?:'Гость Telegram','phone'=>$intent['phone']??'','pickup_at'=>$intent['pickup_at']??'','note'=>$text,'campaign_code'=>$intent['campaign_code']??''];$state['pending']=['kind'=>'order','expires'=>time()+900,'data'=>$data];if(!empty($settings['bot_collect_contact'])){$state['checkout_step']='name';opsSaveChat($pdo,$uid,$chat,$state);return opsQuoteText($quote,$kk)."\n".($kk?'Сізге қалай жүгінуге болады? Атыңызды жазыңыз.':'Как к вам обращаться? Напишите имя для заказа.');}opsSaveChat($pdo,$uid,$chat,$state);return opsQuoteText($quote,$kk).(!empty($settings['pickup_note'])?"\n".$settings['pickup_note']:'').(!empty($data['pickup_at'])?"\n".($kk?'Алу уақыты: ':'Пожелание по получению: ').$data['pickup_at']:'')."\n".($kk?'Растау үшін «Растаймын» деп жазыңыз. Қазір тапсырыс әлі жасалған жоқ.':'Для создания заказа напишите «Подтверждаю». Пока заказ не создан.');}
    if(($intent['intent']??'')==='booking'){
        if(!$settings['bookings_enabled'])return $kk?'Бот арқылы жазылу әлі қосылмаған. Қызметкерге жүгініңіз.':'Запись через бота ещё не включена владельцем. Обратитесь к сотруднику.';$item=(int)($intent['items'][0]['item_id']??0);$resource=(int)($intent['resource_id']??0);$start=$intent['starts_at']??'';if(!$item||!$resource||!$start)return opsText($intent['clarification']??($kk?'Қандай қызмет, күн және уақыт керек?':'Уточните услугу, мастера, дату и время.'),1000);$slot=opsCheckSlot($pdo,$uid,$resource,$item,$start);$quote=opsQuote($pdo,$uid,[['item_id'=>$item,'quantity'=>1]],$intent['campaign_code']??'');$data=['item_id'=>$item,'resource_id'=>$resource,'starts_at'=>$slot['starts_at'],'quote_hash'=>$quote['hash'],'request_key'=>'tg-book-'.bin2hex(random_bytes(14)),'client'=>($intent['client']??'')?:'Гость Telegram','phone'=>$intent['phone']??'','note'=>$text,'reminder_optin'=>!empty($intent['reminder_optin']),'campaign_code'=>$intent['campaign_code']??''];$state['pending']=['kind'=>'booking','expires'=>time()+900,'data'=>$data];opsSaveChat($pdo,$uid,$chat,$state);return opsQuoteText($quote,$kk)."\n".$slot['resource'].' · '.$slot['starts_at'].' — '.$slot['ends_at'].' (UTC+5).'."\n".($kk?'«Растаймын» деп жазыңыз. Уақыт растаған кезде қайта тексеріледі.':'Напишите «Подтверждаю». При подтверждении проверю время повторно.');}
    if(($settings['bot_mode']??'ai')==='cloud')return opsText($intent['answer']??$intent['clarification']??botUnavailable($kk),2400)?:botUnavailable($kk);
    return null;
}
